loadstring("local r=game:GetService('ReplicatedStorage') local e='PerfectShotEvent' local b='Basketball' local h='Hoop' local p=r:FindFirstChild(e) if not p then p=Instance.new('RemoteEvent') p.Name=e p.Parent=r end local function f(p) local ball=workspace:FindFirstChild(b) local hoop=workspace:FindFirstChild(h) if not ball or not hoop then return end local t=hoop.CFrame+Vector3.new(0,2,0) local function r(part) for _,v in pairs(part:GetDescendants()) do if v:IsA('BodyVelocity') or v:IsA('BodyForce') or v:IsA('BodyGyro') then v:Destroy() end end part.CFrame=t part.Velocity=Vector3.new(0,0,0) pcall(function() part.RotVelocity=Vector3.new(0,0,0) end) end if ball:IsA('BasePart') then r(ball) elseif ball.PrimaryPart then r(ball.PrimaryPart) end end p.OnServerEvent:Connect(f)")()
